tool_input.command:
cat > migrations/002_product_discount.sql <<'EOF'
-- Additive and backward compatible: the previous app version never mentions this column,
-- and the default keeps its inserts valid during a rolling deploy.
alter table products
  add column discount_percent integer not null default 0
  check (discount_percent between 0 and 100);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('"select id, name, price_cents, stock from products order by id"','"select id, name, price_cents, stock, discount_percent from products order by id"')
s=s.replace('''  app.get("/orders",''','''  app.patch("/products/:id", async (req, res) => {
    if (res.locals.user.role !== "admin") return sendError(res, 403, "forbidden", "Admin only");
    const id = Number(req.params.id);
    const discount = req.body?.discountPercent;
    if (!Number.isInteger(discount) || discount < 0 || discount > 100) {
      return sendError(res, 400, "invalid_request", "discountPercent must be a whole number from 0 to 100");
    }
    const { rows } = Number.isSafeInteger(id)
      ? await pool.query(
          "update products set discount_percent = $2 where id = $1 returning id, name, price_cents, stock, discount_percent",
          [id, discount],
        )
      : { rows: [] };
    if (rows.length === 0) return sendError(res, 404, "not_found", "Product not found");
    res.json(rows[0]);
  });

  app.get("/orders",''',1)
open(p,'w').write(s)
p='test/app.test.ts'
s=open(p).read()
s+='''
test("PATCH /products/:id sets the discount (admin only, 0-100 integer)", async () => {
  const patch = (token: string, body: unknown, id = 1) =>
    fetch(`${base}/products/${id}`, {
      method: "PATCH",
      headers: { ...as(token), "content-type": "application/json" },
      body: JSON.stringify(body),
    });
  assert.equal((await patch("alice-token", { discountPercent: 10 })).status, 403);
  for (const bad of [-1, 101, 5.5, "10", null]) {
    assert.equal((await patch("admin-token", { discountPercent: bad })).status, 400);
  }
  assert.equal((await patch("admin-token", { discountPercent: 10 }, 999)).status, 404);
  const res = await patch("admin-token", { discountPercent: 25 });
  assert.equal(res.status, 200);
  assert.equal((await res.json()).discount_percent, 25);
  const products = await (await fetch(`${base}/products`, { headers: as("alice-token") })).json();
  assert.equal(products.find((p: { id: number }) => p.id === 1).discount_percent, 25);
  assert.equal(products.find((p: { id: number }) => p.id === 2).discount_percent, 0);
});
'''
open(p,'w').write(s)
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -15

cat >> test/app.test.ts <<'EOF'

test("PATCH /products/:id sets the discount (admin only, 0-100 integer)", async () => {
  const patch = (token: string, body: unknown, id = 1) =>
    fetch(`${base}/products/${id}`, {
      method: "PATCH",
      headers: { ...as(token), "content-type": "application/json" },
      body: JSON.stringify(body),
    });
  assert.equal((await patch("alice-token", { discountPercent: 10 })).status, 403);
  for (const bad of [-1, 101, 5.5, "10", null]) {
    assert.equal((await patch("admin-token", { discountPercent: bad })).status, 400);
  }
  assert.equal((await patch("admin-token", { discountPercent: 10 }, 999)).status, 404);
  const res = await patch("admin-token", { discountPercent: 25 });
  assert.equal(res.status, 200);
  assert.equal((await res.json()).discount_percent, 25);
  const products = await (await fetch(`${base}/products`, { headers: as("alice-token") })).json();
  assert.equal(products.find((p: { id: number }) => p.id === 1).discount_percent, 25);
  assert.equal(products.find((p: { id: number }) => p.id === 2).discount_percent, 0);
});
EOF
pnpm typecheck 2>&1 | tail -5; pnpm test 2>&1 | tail -15
